/**
 * User Identity and Display Presentation Helpers
 */

/**
 * Formats a user email for UI presentation:
 * - Real user emails (e.g. alice@example.com, bob@gmail.com, user@domain.org) are preserved unchanged.
 * - Internal synthetic test artifacts (e.g. testuser_random_xyz987@example.com) generated by automated tests
 *   are cleanly presented using the authenticated user's display name.
 * - Missing or empty email falls back to a clean address based on the user's name or 'player@chesscoach.local'.
 */
export function formatDisplayEmail(rawEmail?: string | null, displayName?: string | null): string {
  const trimmed = rawEmail?.trim();

  // Specifically detect automated test fixture emails (e.g. testuser_random_xyz987@example.com)
  const isSyntheticTestAccount = Boolean(trimmed && /^testuser_random_[a-z0-9_]+@/i.test(trimmed));

  if (!trimmed || isSyntheticTestAccount) {
    const cleanName = (displayName || '')
      .toLowerCase()
      .replace(/[^a-z0-9]/g, '');
    return `${cleanName || 'player'}@chesscoach.local`;
  }

  return trimmed;
}
